mapper.insert:
insert into workflow_run (
    trigger_source, operator_id, operator_type, session_id,
    status, current_node_key, cost_ms, error_message, started_at, ended_at
) values (
    #{triggerSource}, #{operatorId}, #{operatorType}, #{sessionId},
    #{status}, #{currentNodeKey}, #{costMs}, #{errorMessage}, #{startedAt}, #{endedAt}
)

mapper.update:
update workflow_run
set status = #{status},
    error_message = #{errorMessage},
    ended_at = #{endedAt}
where 1 = 1
  and run_id = #{runId}

mapper.select:
select trigger_source, operator_id, operator_type, session_id, status, current_node_key, cost_ms, error_message, started_at, ended_at, created_at, updated_at from workflow_run where 1 = 1
and status = #{status}
order by started_at desc limit #{pageSize} offset #{offset}

mapper.delete:
delete from workflow_run
where 1 = 1
  and started_at < #{cutOff}
order by started_at asc
limit #{limit}

mapper.select:
select run_id
from workflow_run
where 1 = 1
  and started_at < #{cutOff}
order by started_at asc
limit #{limit}
